import{_ as i,a0 as r,w as l,s as p,I as o,x as a,a1 as t,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"cron 與 anacron：如何在 Linux 中計劃任務 | LCTT x X-CMD","titleTemplate":false,"description":"cron 與 anacron：如何在 Linux 中計劃任務 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"cron 與 anacron：如何在 Linux 中計劃任務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"cron 與 anacron：如何在 Linux 中計劃任務 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170601 Cron Vs Anacron How to Schedule Jobs Using Anacron on Linux","title":"cron 與 anacron：如何在 Linux 中計劃任務","tag":"201706","desc":""},"relativePath":"201706/20170601 Cron Vs Anacron How to Schedule Jobs Using Anacron on Linux.md","filePath":"[post].md"}'),c={name:"201706/20170601 Cron Vs Anacron How to Schedule Jobs Using Anacron on Linux.md"};function u(b,n,h,k,g,m){const s=r("Link");return l(),p("div",null,[n[22]||(n[22]=o("h1",{id:"cron-與-anacron-如何在-linux-中計劃任務",tabindex:"-1"},[a("cron 與 anacron：如何在 Linux 中計劃任務 "),o("a",{class:"header-anchor",href:"#cron-與-anacron-如何在-linux-中計劃任務","aria-label":"Permalink to “cron 與 anacron：如何在 Linux 中計劃任務”"},"​")],-1)),n[23]||(n[23]=o("p",null,"在本篇中，我們會解釋 cron 和 anacron，並向你展示如何在 Linux 中設置 anacron。我們也會比較這兩個工具。",-1)),o("p",null,[n[1]||(n[1]=a("要",-1)),t(s,{href:"https://www.tecmint.com/linux-cron-alternative-at-command-to-schedule-tasks/"},{default:e(()=>[...n[0]||(n[0]=[a("在一個給定時間或者稍後安排一個任務",-1)])]),_:1}),n[2]||(n[2]=a("，你可以使用 ",-1)),n[3]||(n[3]=o("code",null,"at",-1)),n[4]||(n[4]=a(" 或者 ",-1)),n[5]||(n[5]=o("code",null,"batch",-1)),n[6]||(n[6]=a(" 命令，要使命令能夠重複運行，你可以使用 cron 以及 anacron 工具。",-1))]),o("p",null,[t(s,{href:"https://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:e(()=>[...n[7]||(n[7]=[a("cron",-1)])]),_:1}),n[8]||(n[8]=a(" - 是一個用於運行計劃任務如系統備份、更新等的守護進程。它適合在那些 24X7 不間斷運行的機器如服務器上運行的計劃任務。",-1))]),n[24]||(n[24]=d(`<p>命令/腳本被寫在 cron 任務腳本中，它是在 <code>crontab</code> 文件中被安排的。系統默認的 <code>crontab</code> 文件是 <code>/etc/crontab</code>，但是每個用户也可以創建自己的 <code>crontab</code> 文件來在特定時間運行用户定義的命令。</p><p>要創建一份個人 <code>crontab</code> 文件，只要輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -e</span></span></code></pre></div><h3 id="如何在-linux-中設置-anacron" tabindex="-1">如何在 Linux 中設置 anacron <a class="header-anchor" href="#如何在-linux-中設置-anacron" aria-label="Permalink to “如何在 Linux 中設置 anacron”">​</a></h3><p>anacron 用於以天為單位的頻率運行命令。它的工作與 cron 稍有不同，<strong>它假設機器不會一直開機</strong>。</p><p>cron 也適合在那些不會 24X7 運行如筆記本以及桌面電腦的機器上運行每日、每週以及每月的計劃任務（LCTT 譯註：不適合按小時、分鐘執行任務）。</p><p>假設你有一個計劃任務（比如備份腳本）要使用 cron 在每天半夜運行，也許你以及睡着，那時你的桌面/筆記本電腦已經關機。你的備份腳本就不會被運行。</p><p>然而，如果你使用 anacron，你可以確保在你下次開啓桌面/筆記本電腦的時候，備份腳本會被執行。</p><h3 id="anacron-如何在-linux-工作" tabindex="-1">anacron 如何在 Linux 工作 <a class="header-anchor" href="#anacron-如何在-linux-工作" aria-label="Permalink to “anacron 如何在 Linux 工作”">​</a></h3><p>anacron 任務被列在 <code>/etc/anacrontab</code> 中，任務可以使用下面的格式（anacron 文件中的註釋必須以 <code>#</code> 號開始）安排。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>period   delay   job-identifier   command</span></span></code></pre></div><p>從上面的格式中：</p><ul><li><code>period</code> - 這是任務的頻率，以天來指定，或者是 <code>@daily</code>、<code>@weekly</code>、<code>@monthly</code> 代表每天、每週、每月一次。你也可以使用數字：<code>1</code> - 每天、<code>7</code> - 每週、<code>30</code> - 每月，或者 <code>N</code> - 幾天。</li><li><code>delay</code> - 這是在執行一個任務前等待的分鐘數。</li><li><code>job-id</code> - 這是寫在日誌文件中任務的獨特名字。</li><li><code>command</code> - 這是要執行的命令或 shell 腳本。</li></ul><p>要瀏覽示例文件，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var/spool/anacron/</span></span>
<span class="line"><span>total 12</span></span>
<span class="line"><span>-rw------- 1 root root 9 Jun  1 10:25 cron.daily</span></span>
<span class="line"><span>-rw------- 1 root root 9 May 27 11:01 cron.monthly</span></span>
<span class="line"><span>-rw------- 1 root root 9 May 30 10:28 cron.weekly</span></span></code></pre></div><p>這是實際發生的：</p><ul><li>anacron 會檢查任務是否已經在 <code>period</code> 字段指定的時間被被執行了。如果沒有，則在等待 <code>delay</code> 字段中指定的分鐘數後，執行 <code>command</code> 字段中指定的命令。</li><li>一旦任務被執行了，它會使用 <code>job-id</code>（時間戳文件名）字段中指定的名稱將日期記錄在 <code>/var/spool/anacron</code> 目錄中的時間戳文件中。</li></ul><p>現在讓我們看一個例子。這個會每天運行 <code>/home/aaronkilik/bin/backup.sh</code> 腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@daily    10    example.daily   /bin/bash /home/aaronkilik/bin/backup.sh</span></span></code></pre></div><p>當機器在 <code>backup.sh</code> 期望被運行時是關機的，anacron 會在機器開機十分鐘之後運行它，而不用再等待 7 天。</p><p>這裏有兩個你應該理解的 anacrontab 文件的重要變量：</p><ul><li><p><code>START_HOURS_RANGE</code> - 這個設置任務開始運行的時間範圍（也就是任務只在這幾個小時內運行）。</p></li><li><p><code>RANDOM_DELAY</code> - 這定義添加到用户定義的任務延遲的最大隨機延遲（默認為 45）。</p></li></ul><p>這是你的 anacrontab 文件可能看上去的樣子。</p><p>Anacron – <code>/etc/anacrontab</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/anacrontab: configuration file for anacron</span></span>
<span class="line"><span># See anacron(8) and anacrontab(5) for details.</span></span>
<span class="line"><span>SHELL=/bin/sh</span></span>
<span class="line"><span>PATH=/usr/local/sbin:/usr/local/bin:/sbin:/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span>HOME=/root</span></span>
<span class="line"><span>LOGNAME=root</span></span>
<span class="line"><span># These replace cron&#39;s entries</span></span>
<span class="line"><span>1       5       cron.daily      run-parts --report /etc/cron.daily</span></span>
<span class="line"><span>7       10      cron.weekly     run-parts --report /etc/cron.weekly</span></span>
<span class="line"><span>@monthly        15      cron.monthly    run-parts --report /etc/cron.monthly</span></span>
<span class="line"><span>@daily    10    example.daily   /bin/bash /home/aaronkilik/bin/backup.sh</span></span></code></pre></div><p>下面是 cron 以及 anacron 的比較，幫助你理解何時用他們其中一個。</p><div class="table-wrap"><table><thead><tr><th>cron</th><th>anacron</th></tr></thead><tbody><tr><td>它是守護進程</td><td>它不是守護進程</td></tr><tr><td>適合服務器</td><td>適合桌面/筆記本電腦</td></tr><tr><td>可以讓你以分鐘級運行計劃任務</td><td>只能讓你以天為基礎來運行計劃任務</td></tr><tr><td>關機時不會執行計劃任務</td><td>如果計劃任務到期，機器是關機的，那麼它會在機器下次開機後執行計劃任務</td></tr><tr><td>普通用户和 root 用户都可以使用</td><td>只有 root 用户可以使用（使用特定的配置啓動普通任務）</td></tr></tbody></table></div><p>cron 和 anacron 主要的區別在於 cron 能在那些持續運行的機器上有效地運行，而 anacron 是針對那些會在一天內或者一週內會關機的機器。</p><p>如果你還知道其他方式，請在評論欄中與我們分享。</p><hr><p>作者簡介：</p><p>Aaron Kili 是一個 Linux 和 F.O.S.S 愛好者、Linux 系統管理員、網絡開發人員，現在也是 TecMint 的內容創作者，他喜歡和電腦一起工作，堅信共享知識。</p><hr>`,33)),o("p",null,[n[10]||(n[10]=a("via: ",-1)),t(s,{href:"https://www.tecmint.com/cron-vs-anacron-schedule-jobs-using-anacron-on-linux/"},{default:e(()=>[...n[9]||(n[9]=[a("https://www.tecmint.com/cron-vs-anacron-schedule-jobs-using-anacron-on-linux/",-1)])]),_:1})]),o("p",null,[n[14]||(n[14]=a("作者：",-1)),t(s,{href:"https://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...n[11]||(n[11]=[a("Aaron Kili",-1)])]),_:1}),n[15]||(n[15]=a(" 譯者：",-1)),t(s,{href:"https://github.com/geekpi"},{default:e(()=>[...n[12]||(n[12]=[a("geekpi",-1)])]),_:1}),n[16]||(n[16]=a(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:e(()=>[...n[13]||(n[13]=[a("wxy",-1)])]),_:1})]),o("p",null,[n[19]||(n[19]=a("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[17]||(n[17]=[a("LCTT",-1)])]),_:1}),n[20]||(n[20]=a(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:e(()=>[...n[18]||(n[18]=[a("Linux中國",-1)])]),_:1}),n[21]||(n[21]=a(" 榮譽推出",-1))])])}const L=i(c,[["render",u]]);export{y as __pageData,L as default};
